func (registry *blockRegistry) ByID(id data.BlockID) (data.Block, bool) {
	value, ok := registry.byID[id]
	return value.Clone(), ok
}
func (registry *blockRegistry) ByName(name string) (data.Block, bool) {
	value, ok := registry.byName[name]
	return value.Clone(), ok
}
func (registry *blockRegistry) All() data.Blocks { return registry.all.Clone() }
